using System;using System.Collections.Generic;class MeterLatencyProbe{static void Main(){var delays=new List<long>();for(int i=0;i<8;i++){var timer=System.Diagnostics.Stopwatch.StartNew();try{FluentAbletonMeter.ReadMaster();delays.Add(timer.ElapsedMilliseconds);}catch{}}delays.Sort();Console.WriteLine("RPC samples="+delays.Count+" medianMs="+(delays.Count>0?delays[delays.Count/2]:-1));}}
